#[Test]
public function bulkCancelGoesThroughDomainAndSkipsShipped(): void
{
    $keyboard = ProductId::fromString(Catalog::KEYBOARD);
    $orders = self::getContainer()->get(OrderRepository::class);
    $paid = Order::place(OrderId::generate(), CustomerId::generate());
    $paid->addItem($keyboard, 2, new Money(300_00, Currency::CZK));
    $paid->confirm();
    $paid->markPaid();
    $orders->save($paid);
    $shipped = Order::place(OrderId::generate(), CustomerId::generate());
    $shipped->addItem($keyboard, 1, new Money(300_00, Currency::CZK));
    $shipped->confirm();
    $shipped->markPaid();
    $shipped->ship();
    $orders->save($shipped);

    $token = $this->client->request('GET', '/admin/legacy/orders')->filter('input[name="_csrf"]')->first()->attr('value');
    $this->client->request('POST', '/admin/legacy/orders_bulk', [
        'ids' => [$paid->id->value, $shipped->id->value],
        'action' => 'storno',
        '_csrf' => $token,
    ]);

    self::getContainer()->get(EntityManagerInterface::class)->clear();
    $cancelled = $orders->get($paid->id);
    self::assertSame(OrderStatus::Cancelled, $cancelled->status);
    self::assertSame(600_00, $cancelled->refundDue->amountInCents);
    self::assertSame(OrderStatus::Shipped, $orders->get($shipped->id)->status);
    // zůstala jen rezervace odeslané objednávky
    self::assertSame(9, self::getContainer()->get(StockItemRepository::class)->get($keyboard)->available());
}

